{
  "thought": "内心的简短独白或想法",
  "stateUpdates": [
    { "path": "attributes.<schema字段ID>", "op": "set", "value": "符合该字段定义的值" }
  ],
  "intents": [
    { "type": "action", "op": "glance_around", "duration": 0.6 },
